mapper.select:
SELECT *
FROM document_chunk
WHERE file_id = #{fileId}
  AND tenant_id = #{tenantId}
  AND knowledge_id = #{knowledgeId}
  AND public_id = #{chunkPublicId}
FOR UPDATE

SELECT *
FROM document_chunk
WHERE file_id = #{fileId}
  AND tenant_id = #{tenantId}
  AND knowledge_id = #{knowledgeId}
  AND position = #{position}
  AND overlap_source_chunk_id = #{sourceChunkId}
FOR UPDATE

mapper.update:
UPDATE document_chunk
SET content = #{content},
    token_count = #{tokenCount},
    content_hash = #{contentHash},
    status = 0,
    is_modified = TRUE,
    index_content = NULL,
    last_error = NULL,
    lock_version = lock_version + 1
WHERE tenant_id = #{tenantId}
  AND knowledge_id = #{knowledgeId}
  AND file_id = #{fileId}
  AND public_id = #{chunkPublicId}
  AND status <> 1
  AND lock_version = #{lockVersion}

UPDATE document_chunk
SET status = 0,
    overlap_content = NULL,
    overlap_token_count = 0,
    index_content = NULL,
    last_error = NULL,
    lock_version = lock_version + 1
WHERE tenant_id = #{tenantId}
  AND knowledge_id = #{knowledgeId}
  AND file_id = #{fileId}
  AND id = #{chunkId}
  AND overlap_source_chunk_id = #{sourceChunkId}
  AND status <> 1
  AND lock_version = #{lockVersion}

mapper.delete:
